  ATTRIBUTE use_dsp OF mulOutput_re : SIGNAL IS "yes";
  ATTRIBUTE use_dsp OF mulOutput_im : SIGNAL IS "yes";
  ATTRIBUTE use_dsp OF mulOutput_re_2 : SIGNAL IS "yes";
  ATTRIBUTE use_dsp OF mulOutput_im_2 : SIGNAL IS "yes";

BEGIN
  -- Symmetric Hann

  u_ShiftRegisterRAM : DUT_Test_ip_src_SimpleDualPortRAM_generic
    GENERIC MAP( AddrWidth => 6,
                 DataWidth => 6
                 )
    PORT MAP( clk => clk,
              enb_1_23_0 => enb_1_23_0,
              wr_din => std_logic_vector(rd_2_regin),
              wr_addr => std_logic_vector(rd_2_waddr),
              wr_en => rd_2_wrenb,  -- ufix1
              rd_addr => std_logic_vector(rd_2_raddr),
              dout => rd_2_regout
              );

  u_ShiftRegisterRAM_1 : DUT_Test_ip_src_SimpleDualPortRAM_generic
    GENERIC MAP( AddrWidth => 4,
                 DataWidth => 38
                 )
    PORT MAP( clk => clk,
              enb_1_23_0 => enb_1_23_0,
              wr_din => std_logic_vector(mergedDelay_regin),
              wr_addr => std_logic_vector(mergedDelay_waddr_1),
              wr_en => mergedDelay_wrenb_1,  -- ufix1
              rd_addr => std_logic_vector(mergedDelay_raddr_1),
              dout => mergedDelay_regout
              );

  u_ShiftRegisterRAM_2 : DUT_Test_ip_src_SimpleDualPortRAM_generic
    GENERIC MAP( AddrWidth => 6,
                 DataWidth => 36
                 )
    PORT MAP( clk => clk,
              enb_1_23_0 => enb_1_23_0,
              wr_din => std_logic_vector(mergedDelay_regin_1),
              wr_addr => std_logic_vector(mergedDelay_waddr),
              wr_en => mergedDelay_wrenb,  -- ufix1
              rd_addr => std_logic_vector(mergedDelay_raddr),
              dout => mergedDelay_regout_1
              );

  valid_in_out2 <= valid_in;

  rd_11_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        valid_in_out2_1 <= '0';
      ELSIF enb_1_23_0 = '1' THEN
        valid_in_out2_1 <= valid_in_out2;
      END IF;
    END IF;
  END PROCESS rd_11_process;


  valid_in_out2_2 <= valid_in;

  rd_1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        valid_in_out2_3 <= '0';
      ELSIF enb_1_23_0 = '1' THEN
        valid_in_out2_3 <= valid_in_out2_2;
      END IF;
    END IF;
  END PROCESS rd_1_process;


  valid_in_out2_4 <= valid_in;

  rd_21_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        rd_21_reg <= (OTHERS => '0');
      ELSIF enb_1_23_0 = '1' THEN
        rd_21_reg(0) <= valid_in_out2_4;
        rd_21_reg(2 DOWNTO 1) <= rd_21_reg(1 DOWNTO 0);
      END IF;
    END IF;
  END PROCESS rd_21_process;

  valid_in_out2_5 <= rd_21_reg(2);

  rd_15_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        rd_15_reg <= (OTHERS => '0');
      ELSIF enb_1_23_0 = '1' THEN
        rd_15_reg(0) <= valid_in_out2_4;
        rd_15_reg(2 DOWNTO 1) <= rd_15_reg(1 DOWNTO 0);
      END IF;
    END IF;
  END PROCESS rd_15_process;

  valid_in_out2_6 <= rd_15_reg(2);

  -- Count limited, Unsigned Counter
  --  initial value   = 0
  --  step value      = 1
  --  count to value  = 199
  count_step <= to_unsigned(16#01#, 8);

  count_from <= to_unsigned(16#00#, 8);

  rd_11_1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        HDL_Counter_out1_1 <= to_unsigned(16#00#, 8);
      ELSIF enb_1_23_0 = '1' THEN
        HDL_Counter_out1_1 <= HDL_Counter_out1;
      END IF;
    END IF;
  END PROCESS rd_11_1_process;


  count <= HDL_Counter_out1_1 + count_step;

  rd_13_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        count_1 <= to_unsigned(16#00#, 8);
      ELSIF enb_1_23_0 = '1' THEN
        count_1 <= count;
      END IF;
    END IF;
  END PROCESS rd_13_process;


  rd_12_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        need_to_wrap_1 <= '0';
      ELSIF enb_1_23_0 = '1' THEN
        need_to_wrap_1 <= need_to_wrap;
      END IF;
    END IF;
  END PROCESS rd_12_process;


  
  count_value <= count_1 WHEN need_to_wrap_1 = '0' ELSE
      count_from;

  rd_14_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        count_value_1 <= to_unsigned(16#00#, 8);
      ELSIF enb_1_23_0 = '1' THEN
        count_value_1 <= count_value;
      END IF;
    END IF;
  END PROCESS rd_14_process;


  rd_16_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        rd_16_reg <= (OTHERS => to_unsigned(16#00#, 8));
      ELSIF enb_1_23_0 = '1' THEN
        rd_16_reg(0) <= HDL_Counter_out1;
        rd_16_reg(1 TO 2) <= rd_16_reg(0 TO 1);
      END IF;
    END IF;
  END PROCESS rd_16_process;

  HDL_Counter_out1_2 <= rd_16_reg(2);

  
  count_value_2 <= HDL_Counter_out1_2 WHEN valid_in_out2_6 = '0' ELSE
      count_value_1;

  crp_out_delay1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        count_value_3 <= to_unsigned(16#00#, 8);
      ELSIF enb_1_23_0 = '1' THEN
        count_value_3 <= count_value_2;
      END IF;
    END IF;
  END PROCESS crp_out_delay1_process;


  HDL_Counter_bypass_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        HDL_Counter_bypass_reg <= to_unsigned(16#00#, 8);
      ELSIF enb_1_4600_1 = '1' THEN
        HDL_Counter_bypass_reg <= count_value_3;
      END IF;
    END IF;
  END PROCESS HDL_Counter_bypass_process;

  
  HDL_Counter_out1_3 <= count_value_3 WHEN enb_1_4600_1 = '1' ELSE
      HDL_Counter_bypass_reg;

  HDL_Counter_out1 <= HDL_Counter_out1_3;

  rd_10_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        HDL_Counter_out1_4 <= to_unsigned(16#00#, 8);
      ELSIF enb_1_23_0 = '1' THEN
        HDL_Counter_out1_4 <= HDL_Counter_out1;
      END IF;
    END IF;
  END PROCESS rd_10_process;


  
  need_to_wrap <= '1' WHEN HDL_Counter_out1_4 = to_unsigned(16#C7#, 8) ELSE
      '0';

  rd_17_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        need_to_wrap_2 <= '0';
      ELSIF enb_1_23_0 = '1' THEN
        need_to_wrap_2 <= need_to_wrap;
      END IF;
    END IF;
  END PROCESS rd_17_process;


  rd_18_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        HDL_Counter_out1_5 <= to_unsigned(16#00#, 8);
      ELSIF enb_1_23_0 = '1' THEN
        HDL_Counter_out1_5 <= HDL_Counter_out1;
      END IF;
    END IF;
  END PROCESS rd_18_process;


  
  range_hit <= '1' WHEN HDL_Counter_out1_5 > to_unsigned(16#FE#, 8) ELSE
      '0';

  rd_19_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        range_hit_1 <= '0';
      ELSIF enb_1_23_0 = '1' THEN
        range_hit_1 <= range_hit;
      END IF;
    END IF;
  END PROCESS rd_19_process;


  HDL_Counter_out2 <= need_to_wrap_2 OR range_hit_1;

  rd_20_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        HDL_Counter_out2_1 <= '0';
      ELSIF enb_1_23_0 = '1' THEN
        HDL_Counter_out2_1 <= HDL_Counter_out2;
      END IF;
    END IF;
  END PROCESS rd_20_process;


  HDL_Counter_out2_3 <= HDL_Counter_out2_2;

  rd_22_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        rd_22_reg <= (OTHERS => '0');
      ELSIF enb_1_23_0 = '1' THEN
        rd_22_reg(0) <= HDL_Counter_out2_3;
        rd_22_reg(2 DOWNTO 1) <= rd_22_reg(1 DOWNTO 0);
      END IF;
    END IF;
  END PROCESS rd_22_process;

  HDL_Counter_out2_4 <= rd_22_reg(2);

  
  HDL_Counter_out2_5 <= HDL_Counter_out2_4 WHEN valid_in_out2_5 = '0' ELSE
      HDL_Counter_out2_1;

  crp_out_delay2_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        HDL_Counter_out2_6 <= '0';
      ELSIF enb_1_23_0 = '1' THEN
        HDL_Counter_out2_6 <= HDL_Counter_out2_5;
      END IF;
    END IF;
  END PROCESS crp_out_delay2_process;


  Delay_bypass_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        Delay_bypass_reg <= '0';
      ELSIF enb_1_4600_1 = '1' THEN
        Delay_bypass_reg <= HDL_Counter_out2_6;
      END IF;
    END IF;
  END PROCESS Delay_bypass_process;

  
  HDL_Counter_out2_2 <= HDL_Counter_out2_6 WHEN enb_1_4600_1 = '1' ELSE
      Delay_bypass_reg;

  HDL_Counter_out2_7 <= HDL_Counter_out2_2;

  rd_0_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        HDL_Counter_out2_8 <= '0';
      ELSIF enb_1_23_0 = '1' THEN
        HDL_Counter_out2_8 <= HDL_Counter_out2_7;
      END IF;
    END IF;
  END PROCESS rd_0_process;


  Delay_out1_1 <= Delay_out1;

  rd_2_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        Delay_out1_2 <= '0';
      ELSIF enb_1_23_0 = '1' THEN
        Delay_out1_2 <= Delay_out1_1;
      END IF;
    END IF;
  END PROCESS rd_2_process;


  
  HDL_Counter_out2_9 <= Delay_out1_2 WHEN valid_in_out2_3 = '0' ELSE
      HDL_Counter_out2_8;

  crp_out_delay3_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        HDL_Counter_out2_10 <= '0';
      ELSIF enb_1_23_0 = '1' THEN
        HDL_Counter_out2_10 <= HDL_Counter_out2_9;
      END IF;
